#define MIN_FLEX 16		/* below this, columns make room for the flex one */
#define MAX_COLUMN 30		/* a fixed column wider than this is cut */
#define CLAUDE_EVERY 2		/* seconds between looks for Claude Code */
#define ESC_WAIT 50		/* ms after ESC before it counts as the key */
#define DOUBLE_CLICK 400	/* ms between the clicks of a double click */
#define WHEEL_STEP 3		/* rows per turn of the mouse wheel */
#define BACKGROUND_WAIT 100	/* ms for the terminal to tell its background */
#define SAVE_WAIT 500		/* ms of quiet before a changed state is saved */
#define NONE ((size_t)-1)

_Static_assert(UI_SORTS == TUI_COLUMNS, "every list column has a word");

static void restore_state(struct tui *t);

const char *const tui_session_headers[TUI_COLUMNS] = {
	"show.col.started", "show.col.modified", "show.col.messages",
	"show.col.branch", "show.col.prompt"
};

static int ascii_lower(int c)
{
	return c >= 'A' && c <= 'Z' ? c - 'A' + 'a' : c;
}

/* Whether filter is part of text, ignoring the case of ASCII letters. */
int tui_match(const char *text, const char *filter)
{
	size_t i;

	if (*filter == '\0')
		return 1;
	for (; *text != '\0'; text++) {
		for (i = 0; filter[i] != '\0' && text[i] != '\0' &&
		    ascii_lower((unsigned char)text[i]) ==
		    ascii_lower((unsigned char)filter[i]); i++)
			;
		if (filter[i] == '\0')
			return 1;
	}
	return 0;
}

/*
 * Widths for a table on total columns: every column keeps its natural
 * width, flex gets what is left. While that is less than MIN_FLEX, the
 * columns in drop go away in their order (width 0).
 */
void tui_fit_columns(const size_t *natural, size_t count, size_t flex,
    const size_t *drop, size_t drops, size_t total, size_t *out)
{
	size_t used, avail, i, d = 0;

	for (i = 0; i < count; i++)
		out[i] = natural[i];
	for (;;) {
		used = 0;
		for (i = 0; i < count; i++)
			if (i != flex && out[i] > 0)
				used += out[i] + TUI_GAP;
		avail = total > used ? total - used : 0;
		if (avail >= MIN_FLEX || d == drops)
			break;
		out[drop[d++]] = 0;
	}
	out[flex] = avail;
}

size_t tui_selected(const struct tui *t)
{
	return t->view_count > 0 ? t->view[t->cursor] : NONE;
}

/* The list rows for body rows between the chrome: the split, at least one. */
size_t tui_list_rows(const struct tui *t, size_t body)
{
	size_t list;

	if (body < 2)
		return body;
	list = (body * t->split + 500) / 1000;
	if (list < 1)
		list = 1;
	if (list > body - 1)
		list = body - 1;
	return list;
}

static void set_text(char **slot, char *text)
{
	free(*slot);
	*slot = text;
}

static void clear_messages(struct tui *t)
{
	set_text(&t->error, NULL);
	set_text(&t->warning, NULL);
	set_text(&t->info, NULL);
}

/*
 * The order of two directories (indexes into the inventory, which comes
 * sorted by project). Numbers and dates go largest and newest first.
 */
static int compare_dirs(const struct tui *t, size_t a, size_t b)
{
	const struct session_dir_info *x = &t->inv.dirs[a], *y = &t->inv.dirs[b];
	int r = 0;

	switch (t->sort) {
	case SORT_STATE:
		r = (x->state > y->state) - (x->state < y->state);
		break;
	case SORT_PROJECT:
		break;
	case SORT_SESSIONS:
		r = (x->sessions < y->sessions) - (x->sessions > y->sessions);
		break;
	case SORT_SIZE:
		r = (x->size < y->size) - (x->size > y->size);
		break;
	case SORT_MODIFIED:
		r = (x->modified < y->modified) - (x->modified > y->modified);
		break;
	}
	if (r == 0)
		r = (a > b) - (a < b);
	return t->reverse ? -r : r;
}

/* A merge sort: qsort has no room for the sort settings. */
static void sort_view(const struct tui *t, size_t *v, size_t *tmp, size_t n)
{
	size_t half, i, j, k;

	if (n < 2)
		return;
	half = n / 2;
	sort_view(t, v, tmp, half);
	sort_view(t, v + half, tmp, n - half);
	for (i = 0, j = half, k = 0; k < n; k++)
		tmp[k] = j == n || (i < half && compare_dirs(t, v[i], v[j]) <= 0) ?
		    v[i++] : v[j++];
	memcpy(v, tmp, n * sizeof *v);
}

static void reset_details(struct tui *t)
{
	t->detail_cursor = 0;
	t->detail_top = 0;
	t->detail_follow = 1;
}

/* Filters and sorts the list; keep (a directory) stays selected if shown. */
static void build_view(struct tui *t, size_t keep)
{
	size_t *tmp, i, n = 0;

	for (i = 0; i < t->inv.count; i++)
		if (tui_match(t->rows[i].cell[SORT_PROJECT], t->filter) ||
		    tui_match(t->inv.dirs[i].name, t->filter))
			t->view[n++] = i;
	tmp = xmalloc((n + 1) * sizeof *tmp);
	sort_view(t, t->view, tmp, n);
	free(tmp);
	t->view_count = n;
	t->cursor = 0;
	t->top = 0;
	t->anchor = 0;
	t->list_follow = 1;
	for (i = 0; i < n; i++)
		if (t->view[i] == keep)
			t->cursor = t->anchor = i;
	if (tui_selected(t) != keep)
		reset_details(t);
	if (n == 0)
		t->focus = FOCUS_LIST;
}

static void free_details(struct tui_details *d)
{
	size_t i;

	if (!d->loaded)
		return;
	for (i = 0; i < d->count * TUI_COLUMNS; i++)
		free(d->cells[i]);
	free(d->cells);
	d->loaded = 0;
}

static void free_scan(struct tui *t)
{
	size_t i, c;

	for (i = 0; i < t->inv.count; i++) {
		for (c = 0; c < TUI_COLUMNS; c++)
			free(t->rows[i].cell[c]);
		free_details(&t->details[i]);
	}
	free(t->rows);
	free(t->details);
	free(t->view);
	free(t->marked);
	inventory_free(&t->inv);
	t->rows = NULL;
	t->details = NULL;
	t->view = NULL;
	t->marked = NULL;
	t->view_count = 0;
}

/* Reads projects/ again; the selected directory stays selected. */
void tui_scan(struct tui *t)
{
	struct session_dir_info *d;
	struct github_entry *gh;
	char *keep = NULL, *shown;
	size_t i, c, w, n, index = NONE;

	if (t->view_count > 0)
		keep = xstrdup(t->inv.dirs[tui_selected(t)].name);
	free_scan(t);
	if (inventory_scan(t->paths.projects_dir, &t->inv) != 0) {
		shown = path_tilde(t->paths.projects_dir, t->paths.home);
		set_text(&t->error, msg_text("error.read", shown,
		    strerror(errno)));
		free(shown);
	}
	t->rows = xmalloc((t->inv.count + 1) * sizeof *t->rows);
	t->details = xmalloc((t->inv.count + 1) * sizeof *t->details);
	t->view = xmalloc((t->inv.count + 1) * sizeof *t->view);
	t->marked = xmalloc(t->inv.count + 1);
	memset(t->marked, 0, t->inv.count + 1);
	for (c = 0; c < TUI_COLUMNS; c++)
		t->widths[c] = 0;
	for (i = 0; i < t->inv.count; i++) {
		d = &t->inv.dirs[i];
		t->rows[i].cell[SORT_STATE] = format_state(d->state);
		t->rows[i].cell[SORT_PROJECT] = format_project(d, t->paths.home);
		t->rows[i].cell[SORT_SESSIONS] = format_count(d->sessions);
		t->rows[i].cell[SORT_SIZE] = format_size(d->size);
		t->rows[i].cell[SORT_MODIFIED] = format_time(d->modified);
		for (c = 0; c < TUI_COLUMNS; c++) {
			w = text_width(t->rows[i].cell[c]);
			if (w > t->widths[c])
				t->widths[c] = w;
		}
		t->details[i].loaded = 0;
		if (keep != NULL && strcmp(d->name, keep) == 0)
			index = i;
	}
	free(keep);
	build_view(t, index);
	t->github_dead = 0;
	if (github_scan(t->paths.config_file, &gh, &n) == 0) {
		t->github_dead = github_dead(gh, n);
		github_entries_free(gh, n);
	}
	t->check_claude = 1;
}

void tui_init(struct tui *t)
{
	memset(t, 0, sizeof *t);
	t->sort = SORT_PROJECT;
	t->split = 500;
	t->claude_now = claude_running;
	t->click_ms = -DOUBLE_CLICK;
	t->suggest_cursor = NONE;
	t->color = 1;
	t->background = -1;
	claude_paths_init(&t->paths);
	t->settings_path = settings_path(t->paths.home);
	if (settings_load(t->settings_path, &t->settings) != 0)
		t->error = msg_text("tui.settings.read", strerror(errno));
	tui_scan(t);
	restore_state(t);
}

/*
 * Sorting, filter, the selected directory and the split as the last run
 * left them. A directory that is gone leaves the first one selected.
 */
static void restore_state(struct tui *t)
{
	struct ui_state st;
	size_t i, index = NONE;

	t->state_path = ui_state_path(t->paths.home);
	if (ui_state_load(t->state_path, &st) != 0 && t->error == NULL)
		t->error = msg_text("tui.state.read", strerror(errno));
	t->sort = (enum tui_sort)st.sort;
	t->reverse = st.reverse;
	t->split = st.split;
	if (strlen(st.filter) < sizeof t->filter)
		strcpy(t->filter, st.filter);
	for (i = 0; i < t->inv.count && st.selected != NULL; i++)
		if (strcmp(t->inv.dirs[i].name, st.selected) == 0)
			index = i;
	build_view(t, index);
	ui_state_free(&st);
	t->state_saved = tui_state_text(t);
}

char *tui_state_text(const struct tui *t)
{
	struct ui_state st;
	char *filter, *text;

	filter = xstrdup(t->filter);
	st.sort = (size_t)t->sort;
	st.reverse = t->reverse;
	st.filter = filter;
	st.selected = t->view_count > 0 ?
	    xstrdup(t->inv.dirs[tui_selected(t)].name) : NULL;
	st.split = t->split;
	text = ui_state_text(&st);
	ui_state_free(&st);
	return text;
}

/* Whether the state differs from what the file has. */
int tui_state_changed(const struct tui *t)
{
	char *text;
	int changed;

	if (t->state_path == NULL)
		return 0;
	text = tui_state_text(t);
	changed = t->state_saved == NULL || strcmp(text, t->state_saved) != 0;
	free(text);
	return changed;
}

/*
 * Writes the state when it changed. A failed write is said once: it is
 * not tried again until the state changes once more.
 */
void tui_save_state(struct tui *t)
{
	char *text;

	if (!tui_state_changed(t))
		return;
	text = tui_state_text(t);
	if (file_store(t->state_path, text, strlen(text)) != 0)
		set_text(&t->error, msg_text("tui.state.save", strerror(errno)));
	set_text(&t->state_saved, text);
}

/*
 * The background to draw for. Automatic and System go by the terminal's
 * answer; without one light, the look of Terminal.app's default.
 */
int tui_dark(const struct tui *t)
{
	if (t->settings.theme == THEME_AUTO ||
	    t->settings.theme == THEME_SYSTEM)
		return t->background > 0;
	return t->settings.theme == THEME_DARK;
}

const struct theme_colors *tui_theme(const struct tui *t)
{
	if (t->settings.theme == THEME_SYSTEM)
		return tui_dark(t) ? &theme_system_dark : &theme_system_light;
	return tui_dark(t) ? &theme_dark : &theme_light;
}

/* How many values an option of the settings screen has. */
size_t tui_choices(enum tui_option option)
{
	(void)option;
	return THEME_COUNT;
}

size_t tui_choice(const struct tui *t, enum tui_option option)
{
	(void)option;
	return (size_t)t->settings.theme;
}

/* Why an option cannot change now, or NULL. */
const char *tui_why_option(const struct tui *t, enum tui_option option)
{
	(void)option;
	return t->color ? NULL : "tui.why.color";
}

/* running as from claude_running: 1, 0, or -1 with err. */
void tui_set_claude(struct tui *t, int running, int err)
{
	free(t->claude_error);
	t->claude_error = running < 0 ? msg_text("error.process",
	    strerror(err)) : NULL;
	t->claude = running > 0;
	t->check_claude = 0;
}

/* The directory to read sessions of before the next frame, or -1. */
long tui_wanted(const struct tui *t)
{
	size_t i = tui_selected(t);

	if (t->screen != SCREEN_LIST || t->mode == MODE_FIELD ||
	    t->mode == MODE_PLAN)
		return -1;
	return t->view_count > 0 && !t->details[i].loaded ? (long)i : -1;
}

/* Reads every session of a directory in full, as csm -s does. */
void tui_load(struct tui *t, size_t dir)
{
	struct tui_details *d = &t->details[dir];
	struct session_info *infos;
	char **files, **row, *shown;
	size_t count, n = 0, i, c, w;

	files = session_files(t->inv.dirs[dir].path, &count);
	infos = xmalloc((count + 1) * sizeof *infos);
	for (i = 0; i < count; i++) {
		if (session_info_read(files[i], &infos[n]) == 0) {
			n++;
			continue;
		}
		if (t->error == NULL) {
			shown = path_tilde(files[i], t->paths.home);
			set_text(&t->error, msg_text("error.read", shown,
			    strerror(errno)));
			free(shown);
		}
	}
	session_files_free(files, count);
	qsort(infos, n, sizeof *infos, session_compare);
	d->cells = xmalloc((n * TUI_COLUMNS + 1) * sizeof *d->cells);
	for (c = 0; c < TUI_COLUMNS; c++)
		d->widths[c] = text_width(msg(tui_session_headers[c]));
	for (i = 0; i < n; i++) {
		row = d->cells + i * TUI_COLUMNS;
		row[0] = format_time(infos[i].started);
		row[1] = format_time(infos[i].modified);
		row[2] = format_count(infos[i].messages);
		row[3] = infos[i].branch != NULL ? text_clean(infos[i].branch) :
		    xstrdup(msg("value.none"));
		row[4] = infos[i].prompt != NULL ? text_clean(infos[i].prompt) :
		    xstrdup(msg("value.none"));
		for (c = 0; c < TUI_COLUMNS; c++) {
			w = text_width(row[c]);
			if (w > d->widths[c])
				d->widths[c] = w;
		}
		session_info_free(&infos[i]);
	}
	for (c = 0; c < TUI_COLUMNS - 1; c++)
		if (d->widths[c] > MAX_COLUMN)
			d->widths[c] = MAX_COLUMN;
	free(infos);
	d->count = n;
	d->loaded = 1;
}

static void free_trash(struct tui_trash *tr)
{
	size_t i;

	for (i = 0; i < tr->count * TRASH_COLUMNS; i++)
		free(tr->cells[i]);
	free(tr->cells);
	trash_list_free(tr->entries, tr->count);
	free(tr->marked);
	free(tr->path);
	memset(tr, 0, sizeof *tr);
}

/* Reads the trash again; the selected entry stays selected. */
static void load_trash(struct tui *t)
{
	struct tui_trash *tr = &t->trash;
	struct move_ctx ctx;
	char *keep = NULL, *shown, **row;
	size_t i, c, w;

	if (tr->count > 0)
		keep = xstrdup(tr->entries[tr->cursor].name);
	free_trash(tr);
	move_init(&ctx, 0);
	tr->path = trash_path(&ctx);
	move_free(&ctx);
	if (tr->path == NULL) {
		set_text(&t->error, xstrdup(msg("error.trash.home")));
	} else if (trash_list(tr->path, &tr->entries, &tr->count) != 0) {
		shown = path_tilde(tr->path, t->paths.home);
		set_text(&t->error, msg_text("error.read", shown,
		    strerror(errno)));
		free(shown);
	}
	tr->cells = xmalloc((tr->count * TRASH_COLUMNS + 1) * sizeof *tr->cells);
	tr->marked = xmalloc(tr->count + 1);
	memset(tr->marked, 0, tr->count + 1);
	for (i = 0; i < tr->count; i++) {
		row = tr->cells + i * TRASH_COLUMNS;
		row[0] = text_clean(tr->entries[i].name);
		row[1] = format_time(tr->entries[i].removed);
		row[2] = format_size(tr->entries[i].size);
		row[3] = format_entry_project(&tr->entries[i], t->paths.home);
		for (c = 0; c < TRASH_COLUMNS; c++) {
			w = text_width(row[c]);
			if (w > tr->widths[c])
				tr->widths[c] = w;
		}
		tr->total += tr->entries[i].size;
		if (keep != NULL && strcmp(tr->entries[i].name, keep) == 0)
			tr->cursor = i;
	}
	free(keep);
	t->list_follow = 1;
}

/* Moves *pos by a key within count items; page is the visible rows. */
static int move_cursor(size_t *pos, size_t count, size_t page,
    enum key_code code)
{
	size_t old = *pos, step = page > 1 ? page - 1 : 1;

	if (count == 0)
		return 0;
	switch (code) {
	case KEY_UP:
		if (*pos > 0)
			(*pos)--;
		break;
	case KEY_DOWN:
		if (*pos + 1 < count)
			(*pos)++;
		break;
	case KEY_PAGE_UP:
		*pos = *pos > step ? *pos - step : 0;
		break;
	case KEY_PAGE_DOWN:
		*pos = *pos + step < count ? *pos + step : count - 1;
		break;
	case KEY_HOME:
		*pos = 0;
		break;
	case KEY_END:
		*pos = count - 1;
		break;
	default:
		break;
	}
	return *pos != old;
}

/* Moves the first visible row; the cursor may leave the view. */
static void scroll_by(size_t *top, size_t count, size_t rows, int down,
    size_t step)
{
	size_t last = count > rows ? count - rows : 0;

	if (down)
		*top = *top + step < last ? *top + step : last;
	else
		*top = *top > step ? *top - step : 0;
	if (*top > last)
		*top = last;
}

static void filter_changed(struct tui *t)
{
	build_view(t, tui_selected(t));
}

/* Keys while the filter field has them: the list follows every change. */
static void edit_filter(struct tui *t, const struct key *k)
{
	size_t len = strlen(t->filter), n;

	switch (k->code) {
	case KEY_CHAR:
		n = strlen(k->text);
		if (len + n < sizeof t->filter) {
			memcpy(t->filter + len, k->text, n + 1);
			filter_changed(t);
		}
		break;
	case KEY_BACKSPACE:
		if (len == 0)
			break;
		while (len > 0 && ((unsigned char)t->filter[--len] & 0xc0) == 0x80)
			;
		t->filter[len] = '\0';
		filter_changed(t);
		break;
	case KEY_ENTER:
		t->mode = MODE_BROWSE;
		break;
	case KEY_ESC:
		t->mode = MODE_BROWSE;
		t->filter[0] = '\0';
		filter_changed(t);
		break;
	default:
		break;
	}
}

static size_t count_marked(const char *marked, size_t n)
{
	size_t i, k = 0;

	for (i = 0; i < n; i++)
		k += marked[i] != 0;
	return k;
}

/*
 * Why a key of the list screen does nothing now, as a catalogue key, or
 * NULL when it works. The same reason greys its button.
 */
static const char *why_list(const struct tui *t, char key)
{
	const struct session_dir_info *d;
	int change = key == 'm' || key == 'f' || key == 'r' || key == 'U';

	if (!change)
		return NULL;
	if (t->claude)
		return "tui.why.claude";
	if (key == 'U')
		return t->github_dead == 0 ? "tui.why.prune" : NULL;
	if (key == 'r' && count_marked(t->marked, t->inv.count) > 0)
		return NULL;
	if (t->view_count == 0)
		return "tui.why.empty";
	d = &t->inv.dirs[tui_selected(t)];
	if (key == 'm' && d->state != STATE_ACTIVE)
		return "tui.why.move";
	if (key == 'f' && d->state != STATE_ORPHAN)
		return "tui.why.fix";
	return NULL;
}

static const char *why_trash(const struct tui *t, char key)
{
	if ((key == 'u' || key == 'E') && t->trash.count == 0)
		return "tui.why.trash";
	if (key == 'u' && t->claude)
		return "tui.why.claude";
	return NULL;
}

static const char *why_settings(const struct tui *t, char key)
{
	if (key == ' ')
		return tui_why_option(t, (enum tui_option)t->option);
	return NULL;
}

static void add_button(struct tui *t, enum key_code code, const char *keytext,
    const char *label, const char *why)
{
	struct tui_button *b;

	if (t->button_count == TUI_MAX_BUTTONS)
		return;
	b = &t->buttons[t->button_count++];
	memset(b, 0, sizeof *b);
	b->key.code = code;
	if (code == KEY_CHAR)
		strcpy(b->key.text, keytext);
	b->keytext = keytext;
	b->label = label;
	b->why = why;
}

static int has_errors(const struct tui *t)
{
	return report_count(&t->preview, NOTE_ERROR) > 0;
}

static int field_action(const struct tui *t)
{
	return t->action == ACTION_MOVE || t->action == ACTION_FIX;
}

/* The buttons of the bar for the screen and the mode, with their reasons. */
void tui_make_buttons(struct tui *t)
{
	t->button_count = 0;
	if (t->mode == MODE_FIELD) {
		add_button(t, KEY_ENTER, "Enter", "tui.button.next", NULL);
		add_button(t, KEY_TAB, "Tab", "tui.button.complete", NULL);
		add_button(t, KEY_ESC, "Esc", "tui.button.cancel", NULL);
		return;
	}
	if (t->mode == MODE_PLAN) {
		if (has_errors(t) && field_action(t))
			add_button(t, KEY_ENTER, "Enter", "tui.button.back", NULL);
		else if (!t->confirm)
			add_button(t, KEY_ENTER, "Enter", "tui.button.run",
			    has_errors(t) ? "tui.plan.errors" : NULL);
		add_button(t, KEY_ESC, "Esc", "tui.button.cancel", NULL);
		return;
	}
	if (t->screen == SCREEN_HELP) {
		add_button(t, KEY_ESC, "Esc", "tui.button.close", NULL);
		add_button(t, KEY_CHAR, "q", "tui.button.quit", NULL);
		return;
	}
	if (t->screen == SCREEN_TRASH) {
		add_button(t, KEY_ENTER, "Enter", "tui.button.restore",
		    why_trash(t, 'u'));
		add_button(t, KEY_CHAR, "E", "tui.button.delete",
		    why_trash(t, 'E'));
		add_button(t, KEY_CHAR, "l", "tui.button.refresh", NULL);
		add_button(t, KEY_ESC, "Esc", "tui.button.back_list", NULL);
		add_button(t, KEY_CHAR, "?", "tui.button.help", NULL);
		add_button(t, KEY_CHAR, "q", "tui.button.quit", NULL);
		return;
	}
	if (t->screen == SCREEN_SETTINGS) {
		add_button(t, KEY_RIGHT, "\342\206\220\342\206\222",
		    "tui.button.change", why_settings(t, ' '));
		add_button(t, KEY_ESC, "Esc", "tui.button.back_list", NULL);
		add_button(t, KEY_CHAR, "?", "tui.button.help", NULL);
		add_button(t, KEY_CHAR, "q", "tui.button.quit", NULL);
		return;
	}
	add_button(t, KEY_CHAR, "m", "tui.button.move", why_list(t, 'm'));
	add_button(t, KEY_CHAR, "f", "tui.button.fix", why_list(t, 'f'));
	add_button(t, KEY_CHAR, "r", "tui.button.remove", why_list(t, 'r'));
	add_button(t, KEY_CHAR, "t", "tui.button.trash", NULL);
	add_button(t, KEY_CHAR, "l", "tui.button.refresh", NULL);
	add_button(t, KEY_CHAR, "/", "tui.button.filter", NULL);
	add_button(t, KEY_CHAR, ",", "tui.button.settings", NULL);
	add_button(t, KEY_CHAR, "?", "tui.button.help", NULL);
	add_button(t, KEY_CHAR, "q", "tui.button.quit", NULL);
}

static void free_suggestions(struct tui *t)
{
	if (t->completing)
		field_list_free(t->suggest, t->suggest_count);
	t->completing = 0;
	t->suggest = NULL;
	t->suggest_count = 0;
}

/* Back to the candidates (or nothing) once the typed path changes. */
static void drop_completions(struct tui *t)
{
	free_suggestions(t);
	t->suggest = t->candidates;
	t->suggest_count = t->candidate_count;
	t->suggest_cursor = NONE;
	t->suggest_top = 0;
}

/* Forgets the change being prepared. */
static void cancel(struct tui *t)
{
	free_suggestions(t);
	field_list_free(t->candidates, t->candidate_count);
	t->candidates = NULL;
	t->candidate_count = 0;
	t->suggest_cursor = NONE;
	t->suggest_top = 0;
	free(t->action_path);
	t->action_path = NULL;
	free(t->targets);
	t->targets = NULL;
	t->target_count = 0;
	report_free(&t->preview);
	t->preview_top = 0;
	t->confirm = t->yes = 0;
	t->action = ACTION_NONE;
	t->mode = MODE_BROWSE;
	t->dragging = 0;
}

/* The chosen items, or the one under the cursor when none is chosen. */
static void choose_targets(struct tui *t, const char *marked, size_t n,
    size_t cursor)
{
	size_t i;

	t->targets = xmalloc((n + 1) * sizeof *t->targets);
	t->target_count = 0;
	for (i = 0; i < n; i++)
		if (marked[i])
			t->targets[t->target_count++] = i;
	if (t->target_count == 0)
		t->targets[t->target_count++] = cursor;
}

/*
 * One run of the chosen change: a plan (ctx->apply 0) or the change itself.
 * What it says goes to r, as csm -n would print it.
 */
static void run_action(struct tui *t, struct move_ctx *ctx, struct report *r)
{
	const struct session_dir_info *d;
	const struct trash_entry *e;
	char *path, *a, *b, *c;
	size_t i;

	switch (t->action) {
	case ACTION_MOVE:
	case ACTION_FIX:
		path = field_path(t->field.text, t->paths.home);
		if (t->action == ACTION_MOVE)
			move_repo(ctx, t->action_path, path);
		else
			move_fix(ctx, t->action_path, path);
		free(path);
		report_notes(r, ctx, 0);
		if (!ctx->apply)
			report_plan(r, ctx);
		break;
	case ACTION_REMOVE:
		for (i = 0; i < t->target_count; i++) {
			d = &t->inv.dirs[t->targets[i]];
			a = text_clean(d->name);
			b = d->project != NULL ? format_project(d, t->paths.home) :
			    xstrdup(msg("value.none"));
			c = format_state(d->state);
			report_add(r, NOTE_INFO, 0, msg_text("remove.dir", a, b, c));
			free(a);
			free(b);
			free(c);
			trash_remove(ctx, d);
			report_notes(r, ctx, 0);
			move_clear(ctx);
		}
		break;
	case ACTION_PRUNE:
		github_prune(ctx, NULL, 0);
		report_notes(r, ctx, 0);
		break;
	case ACTION_RESTORE:
		trash_restore(ctx, t->trash.entries[t->targets[0]].name);
		report_notes(r, ctx, 0);
		break;
	case ACTION_DELETE:
		for (i = 0; i < t->target_count; i++) {
			e = &t->trash.entries[t->targets[i]];
			a = text_clean(e->name);
			b = format_size(e->size);
			report_add(r, NOTE_INFO, 0, msg_text("empty.entry", a, b));
			free(a);
			free(b);
			trash_delete(ctx, e);
			report_notes(r, ctx, 0);
			move_clear(ctx);
		}
		break;
	case ACTION_NONE:
		break;
	}
}

/* The preview of the change: its plan, nothing changes yet. */
#ifdef CSM_DEBUG
static void log_action(const struct tui *t, const char *what)
{
	size_t i;

	DEBUG_LOG("tui %s: action %d, project %s, field \"%s\"", what,
	    (int)t->action, t->action_path != NULL ? t->action_path : "-",
	    field_action(t) ? t->field.text : "");
	for (i = 0; i < t->target_count; i++)
		DEBUG_LOG("  target %s", t->screen == SCREEN_TRASH ?
		    t->trash.entries[t->targets[i]].name :
		    t->inv.dirs[t->targets[i]].name);
}

static void log_report(const struct report *r, const char *what)
{
	size_t i;

	for (i = 0; i < r->count; i++)
		DEBUG_LOG("  %s [%d] %*s%s", what, (int)r->lines[i].level,
		    (int)(2 * r->lines[i].indent), "", r->lines[i].text);
}
#endif

static void start_plan(struct tui *t)
{
	struct move_ctx ctx;

	report_free(&t->preview);
	t->preview_top = 0;
#ifdef CSM_DEBUG
	log_action(t, "plan");
#endif
	move_init(&ctx, 0);
	run_action(t, &ctx, &t->preview);
	move_free(&ctx);
#ifdef CSM_DEBUG
	log_report(&t->preview, "plan");
#endif
	t->mode = MODE_PLAN;
	t->confirm = !has_errors(t) && (t->action == ACTION_REMOVE ||
	    t->action == ACTION_PRUNE || t->action == ACTION_DELETE);
	t->yes = 0;
}

/* What the status bar says after a change that went well. */
static char *done_text(const struct tui *t)
{
	char *a, *b, *out;

	switch (t->action) {
	case ACTION_MOVE:
	case ACTION_FIX:
		a = path_tilde(t->action_path, t->paths.home);
		b = text_clean(t->field.text);
		out = msg_text(t->action == ACTION_MOVE ? "tui.done.move" :
		    "tui.done.fix", a, b);
		free(a);
		free(b);
		return out;
	case ACTION_REMOVE:
		a = format_count(t->target_count);
		out = msg_text("tui.done.remove", a);
		free(a);
		return out;
	case ACTION_PRUNE:
		return xstrdup(msg("prune.done"));
	case ACTION_RESTORE:
		a = text_clean(t->trash.entries[t->targets[0]].name);
		out = msg_text("tui.done.restore", a);
		free(a);
		return out;
	case ACTION_DELETE:
		return xstrdup(msg("empty.done"));
	case ACTION_NONE:
		break;
	}
	return xstrdup("");
}

/* The first line of a level, with the number of the others. */
static char *first_line(const struct report *r, enum note_level level)
{
	char *more;
	size_t i, n = report_count(r, level);
	char *out = NULL;

	for (i = 0; i < r->count && out == NULL; i++)
		if (r->lines[i].level == level)
			out = xstrdup(r->lines[i].text);
	if (out == NULL || n < 2)
		return out;
	more = format_count(n - 1);
	set_text(&out, msg_text("tui.more", out, more));
	free(more);
	return out;
}

/*
 * Makes the change. Claude Code is looked for once more right before it
 * (emptying the trash does not touch its data). The result goes to the
 * status bar and the lists are read again.
 */
static void execute(struct tui *t)
{
	struct move_ctx ctx;
	struct report r = { NULL, 0, 0 };
	char *error, *warning, *done;
	int running = 0, trash;

	if (t->action != ACTION_DELETE && t->claude_now != NULL)
		running = t->claude_now();
	if (running != 0) {
		tui_set_claude(t, running, errno);
		cancel(t);
		set_text(&t->error, xstrdup(msg(running < 0 ?
		    "tui.why.process" : "tui.why.claude")));
		return;
	}
#ifdef CSM_DEBUG
	log_action(t, "execute");
#endif
	move_init(&ctx, 1);
	run_action(t, &ctx, &r);
	move_free(&ctx);
#ifdef CSM_DEBUG
	log_report(&r, "result");
#endif
	error = first_line(&r, NOTE_ERROR);
	warning = first_line(&r, NOTE_WARNING);
	done = error == NULL && warning == NULL ? done_text(t) : NULL;
	report_free(&r);
	trash = t->screen == SCREEN_TRASH;
	cancel(t);
	tui_scan(t);
	if (trash)
		load_trash(t);
	clear_messages(t);
	t->error = error;
	t->warning = warning;
	t->info = done;
}

static void start_field(struct tui *t, enum tui_action action)
{
	const struct session_dir_info *d = &t->inv.dirs[tui_selected(t)];
	char **found, *shown;
	size_t i, n;

	t->action = action;
	t->action_path = xstrdup(d->project);
	shown = path_tilde(d->project, t->paths.home);
	field_set(&t->field, action == ACTION_MOVE ? shown : "");
	free(shown);
	if (action == ACTION_FIX) {
		found = fix_candidates(d->project, &t->inv,
		    t->paths.config_file, &n);
		t->candidates = xmalloc((n + 1) * sizeof *t->candidates);
		for (i = 0; i < n; i++)
			t->candidates[i] = path_tilde(found[i], t->paths.home);
		t->candidate_count = n;
		fix_candidates_free(found, n);
	}
	drop_completions(t);
	t->mode = MODE_FIELD;
}

/* Tab: the common part of the matching directories, else their list. */
static void complete(struct tui *t)
{
	char **list, *common;
	size_t n;

	list = field_complete(t->field.text, t->paths.home, &n);
	if (n == 0) {
		field_list_free(list, n);
		set_text(&t->info, xstrdup(msg("tui.complete.none")));
		return;
	}
	common = field_common(list, n);
	if (strlen(common) > t->field.len || n == 1) {
		field_set(&t->field, common);
		free(common);
		field_list_free(list, n);
		drop_completions(t);
		return;
	}
	free(common);
	free_suggestions(t);
	t->suggest = list;
	t->suggest_count = n;
	t->suggest_cursor = NONE;
	t->suggest_top = 0;
	t->completing = 1;
}

static void choose_suggestion(struct tui *t, size_t i)
{
	t->suggest_cursor = i;
	field_set(&t->field, t->suggest[i]);
}

static void field_keys(struct tui *t, const struct key *k)
{
	char before[FIELD_MAX];
	size_t pos;

	switch (k->code) {
	case KEY_ESC:
		cancel(t);
		break;
	case KEY_ENTER:
		if (t->field.len == 0)
			set_text(&t->error, xstrdup(msg("tui.field.empty")));
		else
			start_plan(t);
		break;
	case KEY_TAB:
		complete(t);
		break;
	case KEY_UP:
	case KEY_DOWN:
	case KEY_PAGE_UP:
	case KEY_PAGE_DOWN:
		if (t->suggest_count == 0)
			break;
		pos = t->suggest_cursor;
		if (pos == NONE)
			pos = k->code == KEY_UP || k->code == KEY_PAGE_UP ?
			    t->suggest_count - 1 : 0;
		else
			move_cursor(&pos, t->suggest_count, t->lower_rows,
			    k->code);
		choose_suggestion(t, pos);
		break;
	default:
		memcpy(before, t->field.text, t->field.len + 1);
		if (field_key(&t->field, k) && strcmp(before, t->field.text) != 0)
			drop_completions(t);
		break;
	}
}

static void plan_keys(struct tui *t, const struct key *k)
{
	size_t rows = t->lower_rows > 1 ? t->lower_rows - 1 : 1;

	switch (k->code) {
	case KEY_ESC:
		cancel(t);
		break;
	case KEY_LEFT:
	case KEY_RIGHT:
	case KEY_TAB:
	case KEY_BACKTAB:
		if (t->confirm)
			t->yes = !t->yes;
		break;
	case KEY_ENTER:
		if (has_errors(t)) {
			if (field_action(t)) {
				report_free(&t->preview);
				t->mode = MODE_FIELD;
			}
		} else if (t->confirm && !t->yes) {
			cancel(t);
			set_text(&t->info, xstrdup(msg("confirm.no")));
		} else {
			execute(t);
		}
		break;
	case KEY_UP:
	case KEY_PAGE_UP:
		scroll_by(&t->preview_top, t->preview.count, rows, 0,
		    k->code == KEY_UP ? 1 : rows);
		break;
	case KEY_DOWN:
	case KEY_PAGE_DOWN:
		scroll_by(&t->preview_top, t->preview.count, rows, 1,
		    k->code == KEY_DOWN ? 1 : rows);
		break;
	case KEY_HOME:
		t->preview_top = 0;
		break;
	case KEY_END:
		scroll_by(&t->preview_top, t->preview.count, rows, 1,
		    t->preview.count);
		break;
	default:
		break;
	}
}

static void toggle_mark(struct tui *t)
{
	size_t i = tui_selected(t);

	if (i == NONE)
		return;
	t->marked[i] = !t->marked[i];
	t->anchor = t->cursor;
	t->list_follow = 1;
}

static void sort_by(struct tui *t, enum tui_sort sort)
{
	if (t->sort == sort) {
		t->reverse = !t->reverse;
	} else {
		t->sort = sort;
		t->reverse = 0;
	}
	build_view(t, tui_selected(t));
}

static void open_trash(struct tui *t)
{
	t->screen = SCREEN_TRASH;
	t->focus = FOCUS_LIST;
	load_trash(t);
}

/* Help covers the screen it was opened from until Esc. */
static void open_help(struct tui *t)
{
	t->help_back = t->screen;
	t->screen = SCREEN_HELP;
	t->help_top = 0;
}

static void help_keys(struct tui *t, const struct key *k)
{
	size_t rows = t->help_rows > 1 ? t->help_rows - 1 : 1;

	switch (k->code) {
	case KEY_CHAR:
		if (strcmp(k->text, "q") == 0)
			t->quit = 1;
		else if (strcmp(k->text, "?") == 0 || strcmp(k->text, "h") == 0)
			t->screen = t->help_back;
		break;
	case KEY_ESC:
		t->screen = t->help_back;
		break;
	case KEY_UP:
	case KEY_PAGE_UP:
		scroll_by(&t->help_top, t->help_count, t->help_rows, 0,
		    k->code == KEY_UP ? 1 : rows);
		break;
	case KEY_DOWN:
	case KEY_PAGE_DOWN:
		scroll_by(&t->help_top, t->help_count, t->help_rows, 1,
		    k->code == KEY_DOWN ? 1 : rows);
		break;
	case KEY_HOME:
		t->help_top = 0;
		break;
	case KEY_END:
		scroll_by(&t->help_top, t->help_count, t->help_rows, 1,
		    t->help_count);
		break;
	default:
		break;
	}
}

static void press(struct tui *t, char key)
{
	const char *why;

	if (key == 'h')
		key = '?';
	why = why_list(t, key);
	if (why != NULL) {
		set_text(&t->error, xstrdup(msg(why)));
		return;
	}
	switch (key) {
	case 'q':
		t->quit = 1;
		break;
	case 'l':
		tui_scan(t);
		break;
	case '/':
		t->mode = MODE_FILTER;
		t->focus = FOCUS_LIST;
		break;
	case 'o':
		t->sort = (t->sort + 1) % TUI_COLUMNS;
		t->reverse = 0;
		build_view(t, tui_selected(t));
		break;
	case 'O':
		t->reverse = !t->reverse;
		build_view(t, tui_selected(t));
		break;
	case ' ':
		toggle_mark(t);
		break;
	case 'm':
		start_field(t, ACTION_MOVE);
		break;
	case 'f':
		start_field(t, ACTION_FIX);
		break;
	case 'r':
		t->action = ACTION_REMOVE;
		choose_targets(t, t->marked, t->inv.count, tui_selected(t));
		start_plan(t);
		break;
	case 'U':
		t->action = ACTION_PRUNE;
		start_plan(t);
		break;
	case 't':
		open_trash(t);
		break;
	case ',':
		t->screen = SCREEN_SETTINGS;
		t->focus = FOCUS_LIST;
		break;
	case '?':
		open_help(t);
		break;
	}
}

static void list_keys(struct tui *t, const struct key *k)
{
	struct tui_details *d;

	switch (k->code) {
	case KEY_CHAR:
		if (k->text[1] == '\0')
			press(t, k->text[0]);
		break;
	case KEY_TAB:
	case KEY_BACKTAB:
		if (t->focus == FOCUS_DETAILS)
			t->focus = FOCUS_LIST;
		else if (t->view_count > 0)
			t->focus = FOCUS_DETAILS;
		break;
	case KEY_ENTER:
		if (t->view_count > 0)
			t->focus = FOCUS_DETAILS;
		break;
	case KEY_ESC:
		if (t->focus == FOCUS_DETAILS) {
			t->focus = FOCUS_LIST;
		} else if (t->filter[0] != '\0') {
			t->filter[0] = '\0';
			filter_changed(t);
		}
		break;
	default:
		if (t->focus == FOCUS_LIST) {
			if (move_cursor(&t->cursor, t->view_count, t->list_rows,
			    k->code)) {
				reset_details(t);
				t->anchor = t->cursor;
			}
			t->list_follow = 1;
			break;
		}
		d = &t->details[tui_selected(t)];
		if (d->loaded)
			move_cursor(&t->detail_cursor, d->count, t->detail_rows,
			    k->code);
		t->detail_follow = 1;
		break;
	}
}

static void trash_press(struct tui *t, char key)
{
	struct tui_trash *tr = &t->trash;
	const char *why;

	if (key == 'h')
		key = '?';
	why = why_trash(t, key);
	if (why != NULL) {
		set_text(&t->error, xstrdup(msg(why)));
		return;
	}
	switch (key) {
	case 'q':
		t->quit = 1;
		break;
	case 'l':
		load_trash(t);
		break;
	case ' ':
		if (tr->count == 0)
			break;
		tr->marked[tr->cursor] = !tr->marked[tr->cursor];
		t->anchor = tr->cursor;
		t->list_follow = 1;
		break;
	case 'u':
		t->action = ACTION_RESTORE;
		choose_targets(t, "", 0, tr->cursor);
		start_plan(t);
		break;
	case 'E':
		t->action = ACTION_DELETE;
		choose_targets(t, tr->marked, tr->count, tr->cursor);
		start_plan(t);
		break;
	case '?':
		open_help(t);
		break;
	}
}

static void trash_keys(struct tui *t, const struct key *k)
{
	switch (k->code) {
	case KEY_CHAR:
		if (k->text[1] == '\0')
			trash_press(t, k->text[0]);
		break;
	case KEY_ENTER:
		trash_press(t, 'u');
		break;
	case KEY_ESC:
		t->screen = SCREEN_LIST;
		break;
	default:
		if (move_cursor(&t->trash.cursor, t->trash.count, t->list_rows,
		    k->code))
			t->anchor = t->trash.cursor;
		t->list_follow = 1;
		break;
	}
}

/* A value of an option, chosen now; it works at once and is saved at once. */
static void set_option(struct tui *t, enum tui_option option, size_t value)
{
	const char *why = tui_why_option(t, option);

	if (why != NULL) {
		set_text(&t->error, xstrdup(msg(why)));
		return;
	}
	if (value >= tui_choices(option) || tui_choice(t, option) == value)
		return;
	t->settings.theme = (enum theme)value;
	if (settings_save(t->settings_path, &t->settings) != 0)
		set_text(&t->error, msg_text("tui.settings.save",
		    strerror(errno)));
}

/* Left and right step through the values, Space goes round. */
static void settings_keys(struct tui *t, const struct key *k)
{
	enum tui_option option = (enum tui_option)t->option;
	size_t value = tui_choice(t, option), count = tui_choices(option);
	const char *why;

	switch (k->code) {
	case KEY_CHAR:
		if (k->text[1] != '\0')
			break;
		why = why_settings(t, k->text[0] == 'h' ? '?' : k->text[0]);
		if (k->text[0] == 'q')
			t->quit = 1;
		else if (k->text[0] == ',')
			t->screen = SCREEN_LIST;
		else if (k->text[0] == '?' || k->text[0] == 'h')
			open_help(t);
		else if (why != NULL)
			set_text(&t->error, xstrdup(msg(why)));
		else if (k->text[0] == ' ')
			set_option(t, option, (value + 1) % count);
		break;
	case KEY_LEFT:
		set_option(t, option, value > 0 ? value - 1 : value);
		break;
	case KEY_RIGHT:
		set_option(t, option, value + 1 < count ? value + 1 : value);
		break;
	case KEY_ESC:
		t->screen = SCREEN_LIST;
		break;
	default:
		move_cursor(&t->option, OPTION_COUNT, t->list_rows, k->code);
		break;
	}
}

/* A click on row pos of a list: Ctrl adds or takes one, Shift a range. */
static void click_row(struct tui *t, size_t *cursor, char *marked,
    const size_t *index, size_t pos, unsigned mods)
{
	size_t i, from, to;

	if (mods & MOD_CTRL) {
		i = index != NULL ? index[pos] : pos;
		marked[i] = !marked[i];
		t->anchor = pos;
	} else if (mods & MOD_SHIFT) {
		from = t->anchor < pos ? t->anchor : pos;
		to = t->anchor < pos ? pos : t->anchor;
		for (i = from; i <= to; i++)
			marked[index != NULL ? index[i] : i] = 1;
	} else {
		t->anchor = pos;
	}
	*cursor = pos;
}

/* The border between the panels follows the mouse; the split keeps it. */
static void drag_border(struct tui *t, size_t y)
{
	size_t body = t->body_rows, list;

	if (body < 2 || y < t->list_y + 2)
		list = 1;
	else
		list = y - t->list_y - 1;
	if (list > body - 1)
		list = body - 1;
	t->split = (list * 1000 + body / 2) / body;
	while (tui_list_rows(t, body) < list && t->split < 1000)
		t->split++;
	while (tui_list_rows(t, body) > list && t->split > 0)
		t->split--;
}

static int inside(size_t v, size_t from, size_t count)
{
	return v >= from && v - from < count;
}

static void wheel(struct tui *t, const struct key *k)
{
	int down = k->mouse == MOUSE_WHEEL_DOWN;
	size_t items;
	struct tui_details *d;

	if (t->screen == SCREEN_HELP) {
		if (inside(k->y, t->list_y, t->help_rows))
			scroll_by(&t->help_top, t->help_count, t->help_rows,
			    down, WHEEL_STEP);
		return;
	}
	if (t->screen == SCREEN_SETTINGS)
		return;
	if (inside(k->y, t->list_y + 1, t->list_rows)) {
		if (t->screen == SCREEN_TRASH)
			scroll_by(&t->trash.top, t->trash.count, t->list_rows,
			    down, WHEEL_STEP);
		else
			scroll_by(&t->top, t->view_count, t->list_rows, down,
			    WHEEL_STEP);
		t->list_follow = 0;
		return;
	}
	if (!inside(k->y, t->lower_y, t->lower_rows))
		return;
	items = t->lower_rows - (t->items_y - t->lower_y);
	if (t->mode == MODE_FIELD) {
		scroll_by(&t->suggest_top, t->suggest_count, items, down,
		    WHEEL_STEP);
	} else if (t->mode == MODE_PLAN) {
		scroll_by(&t->preview_top, t->preview.count, items, down,
		    WHEEL_STEP);
	} else if (t->screen == SCREEN_LIST && t->view_count > 0) {
		d = &t->details[tui_selected(t)];
		if (!d->loaded)
			return;
		scroll_by(&t->detail_top, d->count, t->detail_rows, down,
		    WHEEL_STEP);
		t->detail_follow = 0;
	}
}

/* A click of the left button, double when dbl. */
static void click(struct tui *t, const struct key *k, int dbl)
{
	struct tui_button *b;
	struct tui_details *d;
	size_t i, pos;

	if (k->y == t->buttons_y) {
		for (i = 0; i < t->button_count; i++) {
			b = &t->buttons[i];
			if (k->x >= b->x0 && k->x < b->x1) {
				tui_key(t, &b->key);
				return;
			}
		}
		return;
	}
	if (k->y == t->answers_y && t->mode == MODE_PLAN && t->confirm) {
		if (k->x >= t->no_x0 && k->x < t->no_x1) {
			t->yes = 0;
			plan_keys(t, &(struct key){ .code = KEY_ENTER });
		} else if (k->x >= t->yes_x0 && k->x < t->yes_x1) {
			t->yes = 1;
			plan_keys(t, &(struct key){ .code = KEY_ENTER });
		}
		return;
	}
	if (k->y == t->sep_y && t->list_rows > 0) {
		t->dragging = 1;
		return;
	}
	if (t->mode == MODE_FIELD) {
		if (!inside(k->y, t->items_y, t->lower_rows -
		    (t->items_y - t->lower_y)))
			return;
		pos = t->suggest_top + (k->y - t->items_y);
		if (pos >= t->suggest_count)
			return;
		choose_suggestion(t, pos);
		if (dbl)
			start_plan(t);
		return;
	}
	if (t->mode == MODE_PLAN)
		return;
	if (k->y == t->list_y && t->screen == SCREEN_LIST) {
		for (i = 0; i < TUI_COLUMNS; i++)
			if (t->col_w[i] > 0 && k->x >= t->col_x[i] &&
			    k->x < t->col_x[i] + t->col_w[i])
				sort_by(t, (enum tui_sort)i);
		return;
	}
	if (inside(k->y, t->list_y + 1, t->list_rows)) {
		t->focus = FOCUS_LIST;
		t->list_follow = 1;
		if (t->screen == SCREEN_SETTINGS) {
			pos = k->y - t->list_y - 1;
			if (pos >= OPTION_COUNT)
				return;
			/* A click on the value takes the next one, as Space. */
			t->option = pos;
			if (k->x >= t->value_x0 && k->x < t->value_x1)
				tui_key(t, &(struct key){ .code = KEY_CHAR,
				    .text = " " });
			return;
		}
		if (t->screen == SCREEN_TRASH) {
			pos = t->trash.top + (k->y - t->list_y - 1);
			if (pos < t->trash.count)
				click_row(t, &t->trash.cursor, t->trash.marked,
				    NULL, pos, k->mods);
			return;
		}
		pos = t->top + (k->y - t->list_y - 1);
		if (pos >= t->view_count)
			return;
		i = tui_selected(t);
		click_row(t, &t->cursor, t->marked, t->view, pos, k->mods);
		if (tui_selected(t) != i)
			reset_details(t);
		if (dbl)
			t->focus = FOCUS_DETAILS;
		return;
	}
	if (t->screen == SCREEN_LIST && t->view_count > 0 &&
	    inside(k->y, t->table_y, t->detail_rows)) {
		d = &t->details[tui_selected(t)];
		pos = t->detail_top + (k->y - t->table_y);
		if (!d->loaded || pos >= d->count)
			return;
		t->focus = FOCUS_DETAILS;
		t->detail_cursor = pos;
	}
}

/*
 * The mouse goes by what the last frame drew. A press ends typing in
 * the filter, as Enter does, and clears the last message.
 */
static void mouse(struct tui *t, const struct key *k)
{
	int dbl;

	switch (k->mouse) {
	case MOUSE_RELEASE:
		t->dragging = 0;
		return;
	case MOUSE_DRAG:
		if (t->dragging)
			drag_border(t, k->y);
		return;
	case MOUSE_WHEEL_UP:
	case MOUSE_WHEEL_DOWN:
		wheel(t, k);
		return;
	case MOUSE_PRESS:
		break;
	}
	if (k->button != 0)
		return;
	clear_messages(t);
	dbl = k->ms - t->click_ms <= DOUBLE_CLICK && k->x == t->click_x &&
	    k->y == t->click_y;
	t->click_ms = dbl ? k->ms - 2 * DOUBLE_CLICK : k->ms;
	t->click_x = k->x;
	t->click_y = k->y;
	if (t->mode == MODE_FILTER)
		t->mode = MODE_BROWSE;
	click(t, k, dbl);
}

void tui_key(struct tui *t, const struct key *k)
{
	if (k->code == KEY_BACKGROUND) {
		t->background = k->dark;
		t->answered = 1;
		return;
	}
	if (k->code == KEY_MOUSE) {
		mouse(t, k);
		return;
	}
	clear_messages(t);
	switch (t->mode) {
	case MODE_FILTER:
		edit_filter(t, k);
		return;
	case MODE_FIELD:
		field_keys(t, k);
		return;
	case MODE_PLAN:
		plan_keys(t, k);
		return;
	case MODE_BROWSE:
		break;
	}
	if (t->screen == SCREEN_HELP)
		help_keys(t, k);
	else if (t->screen == SCREEN_TRASH)
		trash_keys(t, k);
	else if (t->screen == SCREEN_SETTINGS)
		settings_keys(t, k);
	else
		list_keys(t, k);
}

void tui_free(struct tui *t)
{
	cancel(t);
	free_scan(t);
	free_trash(&t->trash);
	clear_messages(t);
	free(t->claude_error);
	free(t->settings_path);
	free(t->state_path);
	free(t->state_saved);
	text_lines_free(t->help_lines, t->help_count);
	claude_paths_free(&t->paths);
}

static void flush(struct screen *s)
{
	char *out;
	size_t len;

	out = screen_flush(s, &len);
	if (out != NULL)
		term_write(out, len);
	free(out);
}

static long now_ms(void)
{
	struct timespec ts;

	if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
		return 0;
	return (long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

/* Feeds the keys in buf to the TUI; incomplete ones stay unless !more. */
static size_t feed(struct tui *t, unsigned char *buf, size_t have, int more)
{
	struct key k;
	size_t used;

	while (have > 0 && !t->quit &&
	    (used = key_decode(buf, have, more, &k)) > 0) {
		k.ms = now_ms();
		if (k.code != KEY_NONE)
			tui_key(t, &k);
		memmove(buf, buf + used, have - used);
		have -= used;
	}
	return have;
}

static void check_claude(struct tui *t, time_t *last)
{
	int r;

	r = claude_running();
	tui_set_claude(t, r, errno);
	*last = time(NULL);
}

/*
 * The event loop. Sessions of the selected directory are read only when
 * no key is waiting, so holding an arrow key does not read every file on
 * the way. The state is saved the same way, after a moment of quiet, and
 * once more on the way out; a signal that ends the program cannot write
 * a file safely.
 */
int tui_run(void)
{
	struct tui t;
	struct screen s;
	unsigned char buf[256];
	size_t have = 0, cols = 80, rows = 24, n;
	enum term_event ev;
	const char *no_color, *colorterm;
	time_t last = 0;
	long wanted, until, left;
	int save;

	if (!isatty(STDIN_FILENO) || !isatty(STDOUT_FILENO)) {
		msg_error("error.tui.terminal");
		return EXIT_USAGE;
	}
	tui_init(&t);
	if (term_open() != 0) {
		msg_error("error.tui.open", strerror(errno));
		tui_free(&t);
		return EXIT_PARTIAL;
	}
	term_size(&cols, &rows);
	no_color = getenv("NO_COLOR");
	t.color = no_color == NULL || no_color[0] == '\0';
	screen_init(&s, cols, rows, t.color);
	colorterm = getenv("COLORTERM");
	s.truecolor = colorterm != NULL && (strcmp(colorterm, "truecolor") == 0 ||
	    strcmp(colorterm, "24bit") == 0);
	/*
	 * The first frame waits a moment for the terminal to tell its
	 * background (term_open asked), so the colours do not jump. A
	 * terminal that does not answer leaves COLORFGBG, if set.
	 */
	t.background = background_dark(getenv("COLORFGBG"));
	until = now_ms() + BACKGROUND_WAIT;
	while (!t.answered && !t.quit && (left = until - now_ms()) > 0 &&
	    term_wait((int)left) == TERM_INPUT) {
		n = term_read(buf + have, sizeof buf - have);
		if (n == 0)
			break;
		have = feed(&t, buf, have + n, have + n < sizeof buf);
	}
	while (!t.quit) {
		if (t.check_claude)
			check_claude(&t, &last);
		tui_render(&t, &s);
		flush(&s);
		wanted = tui_wanted(&t);
		save = have == 0 && wanted < 0 && tui_state_changed(&t);
		ev = term_wait(have > 0 ? ESC_WAIT : wanted >= 0 ? 0 :
		    save ? SAVE_WAIT : CLAUDE_EVERY * 1000);
		switch (ev) {
		case TERM_RESIZE:
			if (term_size(&cols, &rows) == 0)
				screen_resize(&s, cols, rows);
			screen_invalidate(&s);
			break;
		case TERM_TIMEOUT:
			if (have > 0)
				have = feed(&t, buf, have, 0);
			else if (wanted >= 0)
				tui_load(&t, (size_t)wanted);
			else if (save)
				tui_save_state(&t);
			else if (time(NULL) - last >= CLAUDE_EVERY)
				t.check_claude = 1;
			break;
		case TERM_INPUT:
			n = term_read(buf + have, sizeof buf - have);
			if (n == 0) {
				t.quit = 1;
				break;
			}
			have = feed(&t, buf, have + n, have + n < sizeof buf);
			break;
		case TERM_ERROR:
			t.quit = 1;
			break;
		}
	}
	term_close();
	tui_save_state(&t);
	screen_free(&s);
	tui_free(&t);
	return 0;
}
